    addDot(mirrorX, yi, 'mirror', 'Mirror of the y-intercept: (' + fmtNum(mirrorX) + ', ' + fmtNum(yi) + ')',
      'Mirror point', 'Reflecting the y-intercept across the line x = h lands on (2h, a·h² + k). Same height, same distance from the axis — proof that the axis of symmetry is a true mirror line.', 0);
  }
  /* vertex last so it draws on top */
  var vpx = X(st.h), vpy = Y(st.k);
  ctx.save(); ctx.globalAlpha = st.dragging ? 0.30 : 0.16; ctx.fillStyle = TEAL;
  ctx.beginPath(); ctx.arc(vpx, vpy, m.dotR * 2.9, 0, Math.PI * 2); ctx.fill(); ctx.restore();
  dot(ctx, vpx, vpy, m.dotR * 1.12, INK, 1);
  hits.push({
    id: 'vertex', px: vpx, py: vpy,
    tip: 'Vertex (' + fmtNum(st.h) + ', ' + fmtNum(st.k) + ') — drag me',
    title: 'Vertex (h, k)',
    body: 'The vertex is the turning point: k is the minimum value and h fixes the axis of symmetry x = h. Drag it and the dashed mirror line, the mirror pair, and both x-intercepts all follow — the shape never changes.'
  });

  /* ---- labels with leader arrows ---- */
  if (!m.compact) {
    var dimA = 0.22;
    var aSym = showInt ? dimA : 1;
    var aInt = showSym ? dimA : 1;

    /* Axis of symmetry */
    var symLabelX = 3.55, symLabelY = 5.8;
    var b1 = drawParts(ctx, [{ t: 'Axis of symmetry' }], X(symLabelX), Y(symLabelY), 'center', m.fs, INK, aSym);
    arrow(ctx, (b1.x0 + b1.x1) / 2 - b1.w * 0.18, Y(symLabelY) + m.fs * 0.75, X(st.h) + (st.h < symLabelX ? m.fs * 0.35 : -m.fs * 0.35), Y(4.95), INK, m.lw, m.head * 0.8, 0.10, aSym);

    /* x-intercepts */
    var xiy = 1.55;
    var b2 = drawParts(ctx, [{ t: 'x', i: true }, { t: '-intercepts' }], X(6.5), Y(xiy), 'right', m.fs, INK, aInt);
    if (rr) {
      arrow(ctx, b2.x0 - m.fs * 0.25, Y(xiy), X(rr[1]) + m.fs * 0.28, Y(0.3), INK, m.lw, m.head * 0.8, 0.06, aInt);
      arrow(ctx, b2.x0 - m.fs * 0.25, Y(xiy) + m.fs * 0.1, X(rr[0]) + m.fs * 0.30, Y(0.25), INK, m.lw, m.head * 0.8, 0.03, aInt);
    }

    /* y-intercept */
    var yly = -3.55;
    var b3 = drawParts(ctx, [{ t: 'y', i: true }, { t: '−intercept' }], X(-2.25), Y(yly), 'right', m.fs, INK, aInt);
    if (inView(0, yi)) {
      arrow(ctx, b3.x1 + m.fs * 0.25, Y(yly), X(0) - m.fs * 0.5, Y(yi) - m.fs * 0.1, INK, m.lw, m.head * 0.8, -0.05, aInt);
    }

    /* Vertex */
    var vly = -5.45, vlx = 3.9;
    var b4 = drawParts(ctx, [{ t: 'Vertex' }], X(vlx), Y(vly), 'center', m.fs, INK, aSym);
    arrow(ctx, b4.x0 - m.fs * 0.3, Y(vly) - m.fs * 0.15, vpx + m.fs * 0.45, vpy + m.fs * 0.5, INK, m.lw, m.head * 0.8, 0.08, aSym);
  }

  /* equation readout, top-left */
  var eq = eqString();
  ctx.save();
  ctx.font = (m.fs * 1.0) + 'px Georgia, "Times New Roman", serif';
  var w = ctx.measureText(eq).width;
  var ex = X(-6.75), ey = Y(6.45);
  ctx.fillStyle = 'rgba(255,255,255,0.92)';
  ctx.fillRect(ex - 3, ey - m.fs * 0.85, w + 8, m.fs * 1.7);
  ctx.restore();
  drawParts(ctx, [{ t: eq }], ex, ey, 'left', m.fs, TEAL, 1);

  st.hits = hits;
}

/* ---------- chart ---------- */
var chart = new Chart(figCanvas, {
  type: 'scatter',
  data: {
    datasets: [{
      data: curvePoints(),
      showLine: true,
      pointRadius: 0,
      borderColor: TEAL,
      borderWidth: 3,
      borderCapStyle: 'round',
      borderJoinStyle: 'round',
      tension: 0
    }]
  },
  options: {
    responsive: true,
    maintainAspectRatio: false,
    animation: false,
    events: [],
    layout: { padding: 2 },
    plugins: { legend: { display: false }, tooltip: { enabled: false } },
    scales: {
      x: {
        type: 'linear', min: -6.95, max: 6.95,
        grid: { display: false }, border: { display: false }, ticks: { display: false }
      },
      y: {
        type: 'linear', min: -6.95, max: 6.95,
        grid: { display: false }, border: { display: false }, ticks: { display: false }
      }
    }
  },
  plugins: [figPlugin]
});
window.__markRendered();

function rebuild() {
  chart.data.datasets[0].borderWidth = metrics(chart).cw;
  chart.data.datasets[0].data = curvePoints();
  var el = document.getElementById('eqReadout');
  if (el) el.textContent = eqString();
  chart.update('none');
}

/* pulse loop */
var rafActive = false;
function needPulse() { return st.view === 'Intercepts'; }
function loop() {
  st.phase += 0.07;
  chart.draw();
  if (needPulse()) { requestAnimationFrame(loop); } else { rafActive = false; chart.draw(); }
}
function ensureLoop() { if (!rafActive && needPulse()) { rafActive = true; requestAnimationFrame(loop); } }

/* ---------- layout ---------- */
function sizeWrap(w, h) {
  var cs = getComputedStyle(figContainer);
  var padL = parseFloat(cs.paddingLeft) || 0, padT = parseFloat(cs.paddingTop) || 0;
  var s = Math.max(140, Math.min(w, h));
  figWrap.style.width = s + 'px';
  figWrap.style.height = s + 'px';
  figWrap.style.left = (padL + (w - s) / 2) + 'px';
  figWrap.style.top = (padT + (h - s) / 2) + 'px';
  chart.resize();
  rebuild();
}
(function () {
  var cs = getComputedStyle(figContainer);
  var padX = (parseFloat(cs.paddingLeft) || 0) + (parseFloat(cs.paddingRight) || 0);
  var padY = (parseFloat(cs.paddingTop) || 0) + (parseFloat(cs.paddingBottom) || 0);
  sizeWrap(Math.max(0, figContainer.clientWidth - padX), Math.max(0, figContainer.clientHeight - padY));
})();
document.addEventListener('fig-resize', function (e) { sizeWrap(e.detail.width, e.detail.height); });

/* ---------- pointer interaction ---------- */
function relPos(e) {
  var r = figCanvas.getBoundingClientRect();
  return { x: e.clientX - r.left, y: e.clientY - r.top };
}
function grabR() { return Math.max(11, metrics(chart).dotR * 3.2); }
function hitAt(p) {
  var best = null, bd = grabR();
  for (var i = st.hits.length - 1; i >= 0; i--) {
    var d = Math.hypot(st.hits[i].px - p.x, st.hits[i].py - p.y);
    if (d < bd) { bd = d; best = st.hits[i]; }
  }
  return best;
}
figCanvas.addEventListener('pointerdown', function (e) {
  var p = relPos(e);
  var d = Math.hypot(chart.scales.x.getPixelForValue(st.h) - p.x, chart.scales.y.getPixelForValue(st.k) - p.y);
  if (d < grabR() * 1.3) {
    st.dragging = true;
    try { figCanvas.setPointerCapture(e.pointerId); } catch (err) { }
    figCanvas.style.cursor = 'grabbing';
    hideTooltip();
    e.preventDefault();
  }
});
figCanvas.addEventListener('pointermove', function (e) {
  var p = relPos(e);
  if (st.dragging) {
    var nh = chart.scales.x.getValueForPixel(p.x);
    var nk = chart.scales.y.getValueForPixel(p.y);
    nh = Math.max(-5, Math.min(5, Math.round(nh * 2) / 2));
    nk = Math.max(-5.5, Math.min(5, Math.round(nk * 2) / 2));
    if (nh !== st.h || nk !== st.k) { st.h = nh; st.k = nk; rebuild(); }
    return;
  }
  var hit = hitAt(p);
  if (hit) {
    figCanvas.style.cursor = (hit.id === 'vertex') ? 'grab' : 'pointer';
    showTooltip(hit.tip, e);
  } else {
    figCanvas.style.cursor = 'default';
    hideTooltip();
  }
});
function endDrag() { if (st.dragging) { st.dragging = false; figCanvas.style.cursor = 'grab'; chart.draw(); } }
figCanvas.addEventListener('pointerup', endDrag);
figCanvas.addEventListener('pointercancel', endDrag);
figCanvas.addEventListener('pointerleave', function () { hideTooltip(); if (!st.dragging) figCanvas.style.cursor = 'default'; });
figCanvas.addEventListener('click', function (e) {
  var hit = hitAt(relPos(e));
  if (hit) showPopup(hit.title, hit.body);
});

/* ---------- controls ---------- */
function update_stretch(v) {
  st.a = v;
  rebuild();
}
function toggle_annotationView(v) {
  st.view = v;
  rebuild();
  ensureLoop();
}
function trigger_resetVertex() {
  st.h = 1; st.k = -4; st.a = 1;
  var s = document.getElementById('stretchInput');
  if (s) { s.value = 1; document.getElementById('stretchVal').value = '1'; }
  rebuild();
}

/* ---------- demo steps ---------- */
var STEPS = [
  {
    title: 'The labeled parabola',
    narration: 'The teal curve y = (x−1)² − 4 turns at the vertex (1, −4), crosses the x-axis at −1 and 3, and crosses the y-axis at −3. Every feature has a name.',
    state: { annotationView: 'All labels', stretch: 1, vertex: [1, -4] }
  },
  {
    title: 'Reading the intercepts',
    narration: 'Focus on the crossings only: two x-intercepts where the curve meets y = 0, and one y-intercept where it meets x = 0. These are the solutions and the starting height of the quadratic.',
    state: { annotationView: 'Intercepts', stretch: 1, vertex: [1, -4] }
  },
  {
    title: 'The mirror line',
    narration: 'Now emphasize symmetry. The red dashed line through the vertex reflects the curve onto itself: the y-intercept at (0,−3) has a partner at (2,−3), the same height and the same distance from x = 1.',
    state: { annotationView: 'Symmetry', stretch: 1, vertex: [1, -4] }
  },
  {
    title: 'Drag the vertex',
    narration: 'Drag the vertex anywhere on the plane. The dashed axis of symmetry slides to stay under it, the mirror pair stays level, and the x-intercepts move — or disappear when the vertex rises above the x-axis.',
    state: { annotationView: 'All labels', stretch: 1 }
  },
  {
    title: 'Stretch and squeeze',
    narration: 'Increase a and the parabola narrows, pulling the x-intercepts toward the axis of symmetry; decrease a and they spread apart. The axis itself never moves.',
    state: { annotationView: 'Intercepts', stretch: 2.5 }
  }
];

function applyStep(i) {
  st.step = Math.max(0, Math.min(STEPS.length - 1, i));
  var s = STEPS[st.step];
  if (s.state.vertex) { st.h = s.state.vertex[0]; st.k = s.state.vertex[1]; }
  var sel = document.getElementById('annotationViewInput');
  if (sel) { sel.value = s.state.annotationView; }
  st.view = s.state.annotationView;
  var sl = document.getElementById('stretchInput');
  if (sl) { sl.value = s.state.stretch; document.getElementById('stretchVal').value = s.state.stretch; }
  st.a = s.state.stretch;
  var n = document.getElementById('demoNarration');
  if (n) n.innerHTML = '<b>' + s.title + '</b><br>' + s.narration;
  var lab = document.getElementById('stepLabel');
  if (lab) lab.textContent = (st.step + 1) + ' / ' + STEPS.length;
  rebuild();
  ensureLoop();
}
function nextStep() { applyStep(st.step + 1); }
function prevStep() { applyStep(st.step - 1); }

applyStep(0);
// @FIGURE_CODE_END

