// @FIGURE_CODE_BEGIN
var TEAL = '#1b7fa8', RED = '#e02b2b', GRID = '#cccccc', AXIS = '#141414', INK = '#111111';

var figContainer = document.getElementById('container');
var figWrap = document.createElement('div');
figWrap.style.cssText = 'position:absolute;left:0;top:0;';
var figCanvas = document.createElement('canvas');
figCanvas.style.cssText = 'width:100%;height:100%;display:block;touch-action:none;';
figWrap.appendChild(figCanvas);
figContainer.appendChild(figWrap);

var LIM = 7.3;          /* axis domain half-width (extra room for axis letters) */
var AX_END = 6.75;      /* where the axis arrowheads sit */

var st = {
  a: 1, h: 1, k: -4,
  view: 'All labels',
  showEq: false,
  dragging: false,
  hoverKey: null,
  hits: [],
  phase: 0,
  step: 0,
  curveMeta: null
};

/* ---------- geometry helpers ---------- */
function curvePoints() {
  var a = st.a, h = st.h, k = st.k, yTop = 5.55;
  var half = Math.sqrt(Math.max(0, (yTop - k) / a));
  var x0 = h - half, x1 = h + half;
  var cutL = x0 >= -6.35, cutR = x1 <= 6.35;
  x0 = Math.max(x0, -6.35); x1 = Math.min(x1, 6.35);
  st.curveMeta = { x0: x0, x1: x1, cutL: cutL, cutR: cutR };
  if (!(x1 > x0)) return [];
  var pts = [], N = 260;
  for (var i = 0; i <= N; i++) {
    var x = x0 + (x1 - x0) * i / N;
    pts.push({ x: x, y: a * (x - h) * (x - h) + k });
  }
  return pts;
}
function roots() {
  var v = -st.k / st.a;
  if (v < 0) return null;
  var r = Math.sqrt(v);
  return [st.h - r, st.h + r];
}
function fmtNum(v) { return (Math.round(v * 100) / 100).toString(); }
function eqString() {
  var a = st.a, h = st.h, k = st.k;
  var as = (a === 1) ? '' : fmtNum(a);
  var hs = (h === 0) ? 'x' : ('x ' + (h > 0 ? '−' : '+') + ' ' + fmtNum(Math.abs(h)));
  var ks = (k === 0) ? '' : (' ' + (k > 0 ? '+' : '−') + ' ' + fmtNum(Math.abs(k)));
  return 'y = ' + as + '(' + hs + ')²' + ks;
}
function clamp(v, lo, hi) { return Math.max(lo, Math.min(hi, v)); }

/* ---------- canvas drawing helpers ---------- */
function metrics(c) {
  var A = c.chartArea;
  var S = Math.min(A.right - A.left, A.bottom - A.top);
  return {
    S: S,
    fs: Math.max(7, Math.min(17, S * 0.036)),
    dotR: Math.max(2, Math.min(6, S * 0.0125)),
    lw: Math.max(0.8, Math.min(2, S * 0.0035)),
    cw: Math.max(1.6, Math.min(6, S * 0.0088)),
    head: Math.max(3.5, Math.min(11, S * 0.022)),
    compact: S < 255
  };
}
function fontFor(p, size) {
  return (p.i ? 'italic ' : '') + size + 'px Georgia, "Times New Roman", serif';
}
function drawParts(ctx, parts, x, y, align, size, color, alpha, halo) {
  ctx.save();
  ctx.globalAlpha = alpha == null ? 1 : alpha;
  ctx.textBaseline = 'middle';
  var total = 0, i;
  for (i = 0; i < parts.length; i++) { ctx.font = fontFor(parts[i], size); total += ctx.measureText(parts[i].t).width; }
  var sx = align === 'center' ? x - total / 2 : (align === 'right' ? x - total : x);
  ctx.lineJoin = 'round';
  ctx.lineWidth = Math.max(2.5, size * (halo == null ? 0.34 : halo));
  ctx.strokeStyle = '#ffffff';
  var cx = sx;
  for (i = 0; i < parts.length; i++) { ctx.font = fontFor(parts[i], size); ctx.strokeText(parts[i].t, cx, y); cx += ctx.measureText(parts[i].t).width; }
  cx = sx; ctx.fillStyle = color;
  for (i = 0; i < parts.length; i++) { ctx.font = fontFor(parts[i], size); ctx.fillText(parts[i].t, cx, y); cx += ctx.measureText(parts[i].t).width; }
  ctx.restore();
  return { x0: sx, x1: sx + total, w: total };
}
function arrow(ctx, x1, y1, x2, y2, color, lw, head, bow, alpha) {
  var dx = x2 - x1, dy = y2 - y1, len = Math.hypot(dx, dy) || 1;
  bow = bow || 0;
  var cx = (x1 + x2) / 2 - dy / len * bow * len;
  var cy = (y1 + y2) / 2 + dx / len * bow * len;
  ctx.save();
  ctx.globalAlpha = alpha == null ? 1 : alpha;
  ctx.setLineDash([]);
  ctx.strokeStyle = color; ctx.fillStyle = color; ctx.lineWidth = lw; ctx.lineCap = 'round';
  ctx.beginPath(); ctx.moveTo(x1, y1); ctx.quadraticCurveTo(cx, cy, x2, y2); ctx.stroke();
